def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    rows = []
    current_row = []
    i = 0
    n = len(text)

    while i < n:
        # Alan okuma başlangıcı
        if text[i] == '"':
            # Tırnaklı alan
            field = ""
            i += 1  # tırnağı geç
            while True:
                if i >= n:
                    raise ValueError("Hatalı girdi: Kapanmayan tırnak.")
                if text[i] == '"':
                    if i + 1 < n and text[i+1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # Tırnak kapandı
                        i += 1
                        # Kural: Kapanan tırnaktan hemen sonra ayırıcı veya satır sonu gelmeli
                        if i < n and text[i] not in (delimiter, '\n', '\r'):
                            raise ValueError("Hatalı girdi: Kapanan tırnaktan sonra geçersiz karakter.")
                        break
                else:
                    field += text[i]
                    i += 1
            current_row.append(field)
        else:
            # Tırnaksız alan
            start = i
            while i < n and text[i] not in (delimiter, '\n', '\r'):
                i += 1
            current_row.append(text[start:i])

        # Alan bittikten sonra ne var?
        if i < n and text[i] == delimiter:
            # Ayırıcı bulundu, bir sonraki alana geçmek için döngü devam etmeli
            # Ancak eğer ayırıcıdan hemen sonra satır sonu gelirse (örn: "a,\n") 
            # bu durum bir sonraki iterasyonda boş alan olarak eklenmeli.
            i += 1
            if i < n and text[i] in ('\n', '\r'):
                current_row.append("")
                rows.append(current_row)
                current_row = []
                if text[i] == '\r' and i + 1 < n and text[i+1] == '\n':
                    i += 2
                else:
                    i += 1
            elif i >= n: # Metin ayırıcı ile biterse (örn: "a,") son alan boş kabul edilir
                current_row.append("")
                rows.append(current_row)
                current_row = []
                break
        elif i < n and text[i] in ('\n', '\r'):
            # Satır sonu bulundu
            rows.append(current_row)
            current_row = []
            if text[i] == '\r' and i + 1 < n and text[i+1] == '\n':
                i += 2
            else:
                i += 1
        elif i >= n:
            # Metin bitti, eğer son bir satır kaldıysa ekle (metin \n ile bitmiyorsa)
            if current_row:
                rows.append(current_row)
            break
        else:
            # Beklenmedik durum (normalde döngü akışında değil)
            i += 1

    return rows

