            # Metin bitti, eğer son bir satır kaldıysa (metin \n ile bitmiyorsa) ekle
            if current_row:
                rows.append(current_row)
            break
        else:
            # Bu kısım normal akışta beklenmez ama döngü güvenliği için
            i += 1

    return rows

